DECLARE @sql NVARCHAR(MAX) = N'SELECT OrderID, CustomerID, OrderDate, TotalDue FROM Orders WHERE 1=1';
DECLARE @params NVARCHAR(MAX) = N'@CustomerID INT, @StatusFilter VARCHAR(20), @StartDate DATE, @EndDate DATE';

IF @CustomerID IS NOT NULL
    SET @sql += N' AND CustomerID = @CustomerID';
IF @StatusFilter IS NOT NULL
    SET @sql += N' AND OrderStatus = @StatusFilter';
IF @StartDate IS NOT NULL
    SET @sql += N' AND OrderDate >= @StartDate';
IF @EndDate IS NOT NULL
    SET @sql += N' AND OrderDate < @EndDate';

EXEC sp_executesql @sql, @params, @CustomerID, @StatusFilter, @StartDate, @EndDate;

// Cohort assignment: fixed at the customer grain, independent of view filters
Cohort Month = {FIXED [Customer ID] : DATETRUNC('month', MIN([Order Date]))}

// Activity flag for the analysis month selected via parameter
Active in Analysis Month =
IF {FIXED [Customer ID], [Analysis Month Param] :
    COUNTD(IF DATETRUNC('month', [Order Date]) = [Analysis Month Param] THEN [Order ID] END)
} > 0
THEN 1 ELSE 0 END

// Retention rate per cohort, aggregated in the view
Retention Rate = SUM([Active in Analysis Month]) / COUNTD([Customer ID])

